args.sql:
SELECT t.tradereg
FROM trader t
JOIN enforcementactions ea ON t.tradereg = ea.invdetref
JOIN compliancecase cc ON ea.compref2 = cc.compreg
WHERE (
    t.trading_performance->'risklevel'->>'risklevel' = 'High'
)
AND (
    ea.esclvl = 'Significant'
)
AND (
    cc.lastrevdt >= DATE '2025-02-02' - INTERVAL '1 month'
);

